import{_ as t,o as a,c as r,a3 as o}from"./chunks/framework.D1iekJsc.js";const p=JSON.parse('{"title":"Agnes AI","description":"Agnes AI 免費多模態 API：官網入口、Free Access 獲取 Key、文本/圖片/視頻模型列表，以及在 MiniTavern 中的填法。","frontmatter":{"title":"Agnes AI","description":"Agnes AI 免費多模態 API：官網入口、Free Access 獲取 Key、文本/圖片/視頻模型列表，以及在 MiniTavern 中的填法。","head":[["meta",{"name":"keywords","content":"酒館,AI酒館,Ai酒館,迷你酒館,超迷你酒館,MiniTavern,AI夥伴,AI朋友,Ai本地聊天,Silly Tavern,SillyTavern,手機玩Silly Tavern,Silly Tavern手機版,Silly Tavern安卓,Silly Tavern蘋果,AI角色扮演,角色卡,角色扮演,AI聊天,手機AI,離線AI,AI劇情,本地大模型,本地模型,Ollama,LM Studio,世界書,正則,BYOK,使用手冊,教學,character card,AI roleplay,AI companion"}],["meta",{"property":"og:title","content":"Agnes AI · MiniTavern Docs"}],["meta",{"property":"og:description","content":"Agnes AI 免費多模態 API：官網入口、Free Access 獲取 Key、文本/圖片/視頻模型列表，以及在 MiniTavern 中的填法。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/zh-TW/free-cloud/agnes-ai"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/zh-TW/free-cloud/agnes-ai"}]]},"headers":[],"relativePath":"zh-TW/free-cloud/agnes-ai.md","filePath":"zh-TW/free-cloud/agnes-ai.md","lastUpdated":1787224147000}'),n={name:"zh-TW/free-cloud/agnes-ai.md"};function d(s,e,i,l,h,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="agnes-ai" tabindex="-1">Agnes AI <a class="header-anchor" href="#agnes-ai" aria-label="Permalink to &quot;Agnes AI&quot;">​</a></h1><p>新加坡 Sapiens AI 旗下的多模態模型服務：同一套 OpenAI 兼容網關覆蓋<strong>文本對話、生圖、視頻</strong>。提供 <strong>Free Access（免費試用檔）</strong>，適合無付費 Key 時開聊與試生圖；額度與限速以控制台為準。</p><h2 id="官網與入口" tabindex="-1">官網與入口 <a class="header-anchor" href="#官網與入口" aria-label="Permalink to &quot;官網與入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>資源</th><th>地址</th></tr></thead><tbody><tr><td>國際站</td><td><a href="https://agnes-ai.com/" target="_blank" rel="noreferrer">agnes-ai.com</a></td></tr><tr><td>中國站</td><td><a href="https://agnes-ai.cn/" target="_blank" rel="noreferrer">agnes-ai.cn</a></td></tr><tr><td>API 控制台（註冊 / Key）</td><td><a href="https://platform.agnes-ai.com/" target="_blank" rel="noreferrer">platform.agnes-ai.com</a></td></tr><tr><td>開發者文檔</td><td><a href="https://agnes-ai.com/en/docs/overview" target="_blank" rel="noreferrer">agnes-ai.com/en/docs/overview</a></td></tr><tr><td>模型目錄（GitHub）</td><td><a href="https://github.com/AgnesAI-Labs/AgnesAI-Models" target="_blank" rel="noreferrer">AgnesAI-Labs/AgnesAI-Models</a></td></tr><tr><td>API Base URL</td><td><code>https://apihub.agnes-ai.com/v1</code></td></tr></tbody></table><p>按地區選國際站或中國站即可；<strong>API Key 與 Base URL 以控制台 / 文檔當前顯示為準</strong>。</p><h2 id="免費怎麼獲取-free-access" tabindex="-1">免費怎麼獲取（Free Access） <a class="header-anchor" href="#免費怎麼獲取-free-access" aria-label="Permalink to &quot;免費怎麼獲取（Free Access）&quot;">​</a></h2><ol><li>打開 <a href="https://platform.agnes-ai.com/" target="_blank" rel="noreferrer">platform.agnes-ai.com</a> 註冊並登錄（常見為郵箱註冊；是否要綁卡以頁面為準）。</li><li>進入開發者控制台 → <strong>API Keys</strong> → 創建並複製 Key（一般以 <code>sk-</code> 開頭）。</li><li>在 MiniTavern 用 <strong>自定義 (OpenAI)</strong>（聊天）或 <strong>自定義 (OpenAI Images)</strong>（生圖）填入 Base URL 與 Key，見下文。</li></ol><table tabindex="0"><thead><tr><th>項目</th><th>說明</th></tr></thead><tbody><tr><td>免費方式</td><td><strong>Free Access</strong>：核心 Flash 系列可免費調用（有 RPM / fair-use 限速），適合個人試用與 demo</td></tr><tr><td>付費升級</td><td><strong>Token Plan</strong>：更高 TPS / 月額度，面向生產與高頻 Agent（非必須）</td></tr><tr><td>限速參考（免費檔）</td><td>文本約 <strong>20 RPM</strong>；生圖按分辨率（1K 約 20 RPM，越高越嚴）；視頻約 <strong>1 RPM</strong>（官方 <a href="https://agnes-ai.com/en/docs/tokenplan" target="_blank" rel="noreferrer">Token Plan FAQ</a>）</td></tr><tr><td>綁卡</td><td>Free Access 通常不強制；正式商用或更高限額再考慮 Token Plan</td></tr></tbody></table><blockquote><p>政策會調整。若控制台顯示某模型需 Token Plan，或返回 429，以官網與賬戶權限為準。</p></blockquote><h2 id="模型列表" tabindex="-1">模型列表 <a class="header-anchor" href="#模型列表" aria-label="Permalink to &quot;模型列表&quot;">​</a></h2><p>下列為公開文檔與模型目錄中的常見 ID（<strong>大小寫敏感</strong>）。Flash 多為免費檔；帶 <strong>Pro</strong> 的一般為付費推理模型。</p><h3 id="文本-對話-視覺理解" tabindex="-1">文本（對話 / 視覺理解） <a class="header-anchor" href="#文本-對話-視覺理解" aria-label="Permalink to &quot;文本（對話 / 視覺理解）&quot;">​</a></h3><p>走 Chat Completions：<code>POST /v1/chat/completions</code>。在 MiniTavern 選 <strong>自定義 (OpenAI)</strong>。</p><table tabindex="0"><thead><tr><th>模型 ID</th><th>說明</th></tr></thead><tbody><tr><td><code>agnes-2.5-flash</code></td><td>推薦：對話、編碼、工具調用、多輪與圖像理解；上下文約 512K</td></tr><tr><td><code>agnes-2.0-flash</code></td><td>上一代 Flash，兼容備用</td></tr><tr><td><code>agnes-2.5-pro</code> / <code>agnes-2.5-pro-alpha</code></td><td>付費推理檔（高級編碼 / 科學推理等），<strong>勿當免費檔</strong></td></tr></tbody></table><h3 id="圖片-文生圖-圖生圖" tabindex="-1">圖片（文生圖 / 圖生圖） <a class="header-anchor" href="#圖片-文生圖-圖生圖" aria-label="Permalink to &quot;圖片（文生圖 / 圖生圖）&quot;">​</a></h3><p>走 Images：文生圖與圖生圖均為 <code>POST /v1/images/generations</code>（圖生圖在 body 裡帶 <code>image</code>，<strong>不是</strong> OpenAI 的 <code>/images/edits</code>）。在 MiniTavern 選 <strong>自定義 (OpenAI Images)</strong>，Base URL 同為 <code>https://apihub.agnes-ai.com/v1</code>；App 對自定義協議會按此路由，測連帶參考圖也會打 generations。</p><table tabindex="0"><thead><tr><th>模型 ID</th><th>說明</th></tr></thead><tbody><tr><td><code>agnes-image-2.1-flash</code></td><td>推薦：高信息密度生圖與編輯，靈活尺寸</td></tr><tr><td><code>agnes-image-2.0-flash</code></td><td>文生圖 / 圖生圖，URL 或 Base64 輸出</td></tr></tbody></table><h3 id="視頻-文生視頻-圖生視頻" tabindex="-1">視頻（文生視頻 / 圖生視頻） <a class="header-anchor" href="#視頻-文生視頻-圖生視頻" aria-label="Permalink to &quot;視頻（文生視頻 / 圖生視頻）&quot;">​</a></h3><p>走 Videos：<code>POST /v1/videos</code>（異步任務）。常見 ID：</p><table tabindex="0"><thead><tr><th>模型 ID</th><th>說明</th></tr></thead><tbody><tr><td><code>agnes-video-v2.0</code></td><td>文生視頻、圖生視頻、多圖/關鍵幀等</td></tr><tr><td><code>agnes-video-v2.5</code>（或文檔中的 Video 2.5）</td><td>新一代視頻接口，以<a href="https://agnes-ai.com/en/docs/agnes-video-v20" target="_blank" rel="noreferrer">官方視頻文檔</a>為準</td></tr></tbody></table><p>MiniTavern <strong>當前無內置視頻生成入口</strong>；上表便於對照官網能力。聊天與生圖可先用 Flash 文本 / 圖像模型。</p><h2 id="在-minitavern-裡怎麼填" tabindex="-1">在 MiniTavern 裡怎麼填 <a class="header-anchor" href="#在-minitavern-裡怎麼填" aria-label="Permalink to &quot;在 MiniTavern 裡怎麼填&quot;">​</a></h2><p>通用步驟見 <a href="/ultra_guides/zh-TW/manual/model-link">模型連接</a>。</p><h3 id="聊天" tabindex="-1">聊天 <a class="header-anchor" href="#聊天" aria-label="Permalink to &quot;聊天&quot;">​</a></h3><p>路徑：<strong>設置 → 模型 → 模型連接 → 新建</strong></p><ol><li>平臺選 <strong>自定義 (OpenAI)</strong></li><li>Base URL：<code>https://apihub.agnes-ai.com/v1</code></li><li>粘貼 API Key</li><li>模型 ID 填 <code>agnes-2.5-flash</code>（或控制台列表中的其它文本模型）</li><li><strong>測試</strong> → 成功後設為默認</li></ol><h3 id="生圖" tabindex="-1">生圖 <a class="header-anchor" href="#生圖" aria-label="Permalink to &quot;生圖&quot;">​</a></h3><p>路徑：<strong>設置 → 生圖 → 生圖連接</strong></p><ol><li>平臺選 <strong>自定義 (OpenAI Images)</strong></li><li>Base URL 同上</li><li>同一 Key；模型填 <code>agnes-image-2.1-flash</code> 等</li><li>測連後再用於 <code>/imagine</code> 或生圖入口</li></ol><p>聊天連接與生圖連接可分開：例如聊天用 <code>agnes-2.5-flash</code>，生圖用 <code>agnes-image-2.1-flash</code>。</p><h2 id="相關章節" tabindex="-1">相關章節 <a class="header-anchor" href="#相關章節" aria-label="Permalink to &quot;相關章節&quot;">​</a></h2><ul><li><a href="/ultra_guides/zh-TW/free-cloud/">免費雲端總覽</a> — 其它廠商免費 / 試用額度</li><li><a href="/ultra_guides/zh-TW/free-cloud/#免費生圖怎麼配">免費生圖</a></li><li><a href="/ultra_guides/zh-TW/manual/model-link">模型連接</a></li><li><a href="/ultra_guides/zh-TW/local/image-gen/">生圖模型部署</a> — 本機 A1111 / ComfyUI</li></ul>',32)])])}const m=t(n,[["render",d]]);export{p as __pageData,m as default};
